/**
 * The `pgcrypto` extension. `digest` compares a hex digest. `fipsMode` needs version 1.4 and PostgreSQL 18.
 *
 * Generated by scripts/ext-generate.ts. Do not edit.
 * `minPostgres` for the base methods is 15. A feature
 * a declared version lacks fails with OKM1812.
 */

import type { Fragment } from "../ops/fragment.js";
import { bareCall, digestEquals } from "./call.js";
import { extension, type Extension, type ExtensionOptions } from "./index.js";
import { assertExtFeature } from "./feature.js";

/** `pgcrypto` plus the methods the naming overlay selected. */
export type Pgcrypto = Extension & {
  /**
   * `encode(digest(column, algorithm), 'hex') = hex`.
   *
   * @param algorithm - Digest algorithm, such as `sha256`
   * @param hex - Expected hex digest
   * @returns A where fragment
   */
  digest(algorithm: string, hex: string): Fragment;
  /**
   * `fips_mode()` is true or false on the column's row. Needs pgcrypto 1.4 and PostgreSQL 18.
   *
   * @returns A where fragment
   */
  fipsMode(): Fragment;
};

/**
 * Declares `pgcrypto`.
 *
 * @param options - Schema and version pin
 * @returns The extension object and its methods
 */
export function pgcrypto(options: ExtensionOptions = {}): Pgcrypto {
  const declared = extension("pgcrypto", options);
  const schema = declared.schema;
  return {
    ...declared,
    digest(algorithm: string, hex: string): Fragment {
      return digestEquals(schema, algorithm, hex);
    },
    fipsMode(): Fragment {
      assertExtFeature(options.version, "fips_mode", {
        name: "pgcrypto",
        extension: "1.4",
        postgres: 18,
      });
      return bareCall(schema, "fips_mode");
    },
  };
}
